# -*- coding: utf-8 -*-
import re

with open('app/src/main/java/com/example/data/WorshipData.kt', 'r', encoding='utf-8') as f:
    content = f.read()

match = re.search(r'val sahifaSajjadiya = listOf\((.*?)\)\s+val generalPrayers =', content, re.DOTALL)
if not match:
    print("Could not find sahifaSajjadiya block!")
    exit(1)

block = match.group(1)
elements = re.split(r'(?=Pair\(\"الدعاء)', block)
elements = [e.strip() for e in elements if e.strip()]

for idx in range(len(elements)):
    elements[idx] = elements[idx].rstrip()
    if elements[idx].endswith(','):
        elements[idx] = elements[idx][:-1].rstrip()

text_23 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَأَلْبِسْنِي عَافِيَتَكَ، وَجَلِّلْنِي عَـافِيَتَكَ، وَحَصِّنِّي بِعَـافِيَتِـكَ، وَأكْـرِمْنِي بِعَافِيَتِكَ، وَأغْنِنِي بِعَافِيَتِكَ، وَتَصَدَّقْ عَلَيَّ بِعَافِيَتِكَ، وَهَبْ لِي عَافِيَتَكَ، وَأَفْرِشْنِي عَافِيَتَكَ، وَأَصْلِحْ لِي عَافِيَتَكَ، وَلا تُفَرِّقْ بَيْنِي وَبَيْنَ عَافِيَتِكَ فِي الدُّنْيَا وَالاخِرَةِ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَعَافِنِي عَافِيَةً كَافِيَةً شَافِيَةً عَالِيَةً نَامِيةً، عَافِيَةً تُوَلِّدُ فِي بَدَنِي الْعَافِيَةَ، عَافِيَةَ الدُّنْيَا والاخِرَةِ، وَامْنُنْ عَلَيَّ بِالصِّحَّةِ وَالامْنِ وَالسَّلاَمَةِ فِي دِيْنِي وَبَـدَنِي، وَالْبَصِيـرَةِ فِي قَلْبِي وَالنَّفَاذِ فِي أمُورِيْ وَالْخَشْيَةِ لَكَ، وَالْخَوْفِ مِنْكَ وَالْقُوَّةِ عَلَى مَا أَمَرْتَنِي بِهِ مِنْ طَاعَتِكَ وَالاجْتِنَابِ لِمَـا نَهَيْتَنِي عَنْهُ مِنْ مَعْصِيَتِـكَ.
أللَّهُمَّ وَامْنُنْ عَلَيَّ بِالْحَجِّ وَالْعُمْرَةِ، وَزِيَارَةِ قَبْرِ رَسُولِكَ صَلَوَاتُكَ عَلَيْهِ وَرَحْمَتُكَ وَبَرَكَاتُكَ عَلَيْهِ وَعَلَى آلِهِ، وَآلِ رَسُولِكَ عَلَيْهِمُ السَّلاَمُ أَبَداً مَا أَبْقَيْتَنِي، فِي عَامِي هَذَا وَفِي كُلِّ عَام، وَاجْعَلْ ذَلِكَ مَقْبُولاً مَشْكُوراً مَذْكُوراً لَدَيْكَ، مَذْخُوراً عِنْدَكَ، وَأَنْطِقْ بِحَمْدِكَ وَشُكْرِكَ وَذِكْرِكَ وَحُسْنِ الثَّناءِ عَلَيْكَ لِسَانِي، وَاشْرَحْ لِمَرَاشِدِ دِينِكَ قَلْبِي، وَأَعِذْنِي وَذُرِّيَّتِي مِنَ الشَّيْطَانِ الرَّجِيم وَمِنْ شَرِّ السَّامَّةِ وَالْهَامَّةِ وَالْعَامَّةِ وَاللاَّمَّةِ وَمِنْ شَرِّ كُلِّ شَيْطَان مَرِيد، وَمِنْ شَرِّكُلِّ سُلْطَان عَنِيد، وَمِنْ شَرِّ كُلِّ مُتْرَف حَفِيد، وَمِنْ شَرِّ كُلِّ ضَعِيف وَشَدِيد، وَمِنْ شَرِّكُلِّ شَرِيف وَوَضِيع، وَمِنْ شَرِّ كُلِّ صَغِير وَكَبِير، وَمِنْ شَرِّ كُلِّ قَرِيْب وَبَعِيد، وَمِنْ شَرِّ كُلِّ مَنْ نَصَبَ لِرَسُولِكَ وَلاِهْلِ بَيْتِهِ حَرْبَـاً مِنَ الْجِنِّ وَالانْسِ، وَمِنْ شَرّ كُلِّ دَابَّة أَنْتَ آخِذٌ بِنَاصِيَتِهَا إنَّكَ عَلَى صِرَاط مُسْتَقِيم.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وآلِهِ وَمَنْ أَرَادَنِي بِسُوء فَاصْرِفْهُ عَنِّي وَادْحَرْ عَنِّي مَكْرَهُ، وَادْرَأ عَنِّي شَرَّهُ، وَرُدَّ كَيْدَهُ فِي نَحْرِهِ، وَاجْعَلْ بَيْنَ يَدَيْهِ سَدّاً حَتَّى تُعْمِيَ عَنِّي بَصَرَهُ، وَتُصِمَّ عَنْ ذِكْري سَمْعَهُ، وَتُقْفِلَ دُونَ إخْطَارِي قَلْبَهُ، وَتُخْرِسَ عَنَي لِسَانَهُ، وَتَقْمَعَ رَأسَهُ، وَتُذِلَّ عِزَّهُ، وَتَكْسِرَ جَبَرُوتَهُ، وَتُذِلَّ رَقَبَتَهُ، وَتَفْسَخَ كِبْرَهُ، وَتُؤْمِنَنِي مِنْ جَمِيْعِ ضَرِّهِ وَشَرِّهِ وَغَمْزِهِ وَهَمْزِهِ وَلَمْزِهِ وَحَسَدِهِ وَعَدَاوَتِهِ وَحَبَائِلِهِ وَمَصَائِدِهِ وَرَجْلِهِ وَخَيْلِهِ إنَّكَ عَزِيز قَدِيرٌ."""

text_24 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد عَبْـدِكَ وَرَسُولِـكَ وَأَهْلِ بَيْتِهِ الطَّاهِرِينَ، وَاخْصُصْهُمْ بِأَفْضَلِ صَلَوَاتِكَ وَرَحْمَتِكَ وَبَرَكَاتِكَ وَسَلاَمِكَ، وَاخْصُصِ اللَّهُمَّ وَالِدَيَّ بِالْكَرَامَةِ لَدَيْكَ، وَالصَّلاَةِ مِنْكَ يَا أَرْحَمَ الرَّاحِمِينَ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَأَلْهِمْنِي عِلْمَ مَا يَجبُ لَهُمَا عَلَىَّ إلْهَاماً، وَاجْمَعْ لِي عِلْمَ ذلِكَ كُلِّهِ تَمَامـاً، ثُمَّ اسْتَعْمِلْنِي بِمَا تُلْهِمُنِي مِنْـهُ، وَوَفِّقْنِي لِلنُّفُوذِ فِيمَا تُبَصِّـرُنِيْ مِنْ عِلْمِهِ، حَتَّى لاَ يَفُوتَنِي اسْتِعْمَالُ شَيْء عَلَّمْتَنِيْهِ، وَلاَ تَثْقُلَ أَرْكَانِي عَنِ الْحُفُوفِ فِيمَا أَلْهَمْتَنِيهِ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ كَمَا شَرَّفْتَنَا بِهِ وَصَلِّ عَلَى مُحَمَّد وَآلِهِ كَمَا أَوْجَبْتَ لَنَا الْحَقَّ عَلَى الْخَلْقِ بِسَبَبِهِ.
أللَّهُمَّ اجْعَلْنِي أَهَابُهُمَا هَيْبَةَ السُّلْطَانِ الْعَسُوفِ، وَأَبَرُّهُمَا بِرَّ الاُمِّ الرَّؤُوفِ، وَاجْعَلْ طَاعَتِي لِوَالِدَيَّ وَبِرِّيْ بِهِمَا أَقَرَّ لِعَيْنِي مِنْ رَقْدَةِ الْوَسْنَانِ، وَأَثْلَجَ لِصَدْرِي مِنْ شَرْبَةِ الظَّمْآنِ حَتَّى أوثِرَ عَلَى هَوَايَ هَوَاهُمَا وَاُقَدِّمَ عَلَى رِضَاىَ رِضَاهُمَا وَأَسْتَكْثِرَ بِرَّهُمَا بِي وَإنْ قَلَّ وَأَسْتَقِلَّ بِرِّي بِهِمَا وَإنْ كَثُرَ.
أللَّهُمَّ خَفِّضْ لَهُمَا صَوْتِي، وَأَطِبْ لَهُمَا كَلاَمِي، وَأَلِنْ لَهُمَا عَرِيْكَتِي، وَاعْطِفْ عَلَيْهِمَا قَلْبِي، وَصَيِّرْنِي بِهِمَا رَفِيقاً، وَعَلَيْهِمَا شَفِيقاً.
أللَّهُمَّ اشْكُرْ لَهُمَا تَرْبِيَتِي وَأَثِبْهُمَا عَلَى تَكْرِمَتِي، وَاحْفَظْ لَهُمَا مَا حَفِظَاهُ مِنِّي فِي صِغَرِي.
اللَّهُمَّ وَمَا مَسَّهُمَا مِنِّي مِنْ أَذَىً أَوْ خَلَصَ إلَيْهِمَا عَنِّي مِنْ مَكْرُوه أَوْ ضَاعَ قِبَلِي لَهُمَا مِنْ حَقٍّ فَاجْعَلْهُ حِطَّةً لِذُنُوبِهِمَا وَعُلُوّاً فِي دَرَجَاتِهِمَا وَزِيَادَةً فِي حَسَنَاتِهِمَا يَا مُبَدِّلَ السَّيِّئاتِ بِأَضْعَافِهَا مِنَ الْحَسَنَاتِ.
أللَّهُمَّ وَمَا تَعَدَّيَا عَلَيَّ فِيهِ مِنْ قَوْل، أَوْ أَسْرَفَا عَلَىَّ فِيْهِ مِنْ فِعْل، أَوْ ضَيَّعَاهُ لِي مِنْ حَقٍّ أَوْقَصَّرا بِي عَنْهُ مِنْ وَاجِب فَقَدْ وَهَبْتُهُ وَجُدْتُ بِهِ عَلَيْهِمَا، وَرَغِبْتُ إلَيْكَ فِي وَضْعِ تَبِعَتِهِ عَنْهُمَا فَإنِّي لا أَتَّهِمُهُمَا عَلَى نَفْسِـي، وَلاَ أَسْتَبْطِئُهُمَا فِي بِرِّي، وَلا أكْرَهُ مَا تَوَلَّياهُ مِنْ أَمْرِي يَا رَبِّ فَهُمَا أَوْجَبُ حَقّاً عَلَيَّ، وَأَقْدَمُ إحْسَانـاً إلَيَّ وَأَعْظَمُ مِنَّةً لَـدَيَّ مِنْ أَنْ أقَاصَّهُمَـا بِعَدْل، أَوْ اُجَازِيَهُمَا عَلَى مِثْل، أَيْنَ إذاً يَا إلهِيْ طُولُ شُغْلِهِمَا بِتَرْبِيَتِي؟ وَأَيْنَ شِدَّةُ تَعَبِهِمَا فِي حِرَاسَتِيْ؟ وَأَيْنَ إقْتَارُهُمَا عَلَى أَنْفُسِهِمَا لِلتَّوْسِعَةِ عَلَيَّ؟
هَيْهَاتَ مَا يَسْتَوْفِيَانِ مِنِّي حَقَّهُمَا، وَلاَ اُدْرِكُ مَا يَجِبُ عَلَيَّ لَهُمَا وَلا أَنَا بِقَاض وَظِيفَةَ خِدْمَتِهِمَا.
فَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَأَعِنِّي يَا خَيْرَ مَنِ اسْتُعِينَ بِهِ.
وَوَفِّقْنِي يَا أَهْدَى مَنْ رُغِبَ إلَيْهِ، وَلاَ تَجْعَلْنِي فِي أَهْلِ الْعُقُوقِ لِلابآءِ وَالاُمَّهاتِ يَوْمَ تُجْزى كُلُّ نَفْس بِمَا كَسَبَتْ وَهُمْ لاَيُظْلَمُونَ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِـهِ وَذُرِّيَّتِهِ، وَاخْصُصْ أَبَوَيَّ بِأَفْضَلِ مَا خَصَصْتَ بِهِ آبَاءَ عِبَادِكَ الْمُؤْمِنِينَ وَاُمَّهَاتِهِمْ يَا أَرْحَمَ الـرَّاحِمِينَ.
أللَّهُمَّ لاَ تُنْسِنِي ذِكْرَهُمَا فِي أَدْبَارِ صَلَوَاتِي وَفِي أَناً مِنْ آناءِ لَيْلِي، وَفِي كُلِّ سَاعَة مِنْ سَاعَاتِ نَهَارِي.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَاغْفِرْ لِي بِدُعَائِي لَهُمَا، وَاغْفِرْ لَهُمَـا بِبِرِّهِمَـا بِي، مَغْفِرَةً حَتْمـاً وَارْضَ عَنْهُمَا بِشَفَاعَتِي لَهُمَا رِضَىً عَزْماً، وَبَلِّغْهُمَا بِالْكَرَامَةِ مَوَاطِنَ السَّلاَمَةِ.
أللَّهُمَّ وَإنْ سَبَقَتْ مَغْفِرَتُكَ لَهُمَا فَشَفِّعْهُمَا فِيَّ، وَإنْ سَبَقَتْ مَغْفِرَتُـكَ لِي فَشَفِّعْنِي فِيْهِمَا، حَتّى نَجْتَمِعَ بِرَأفَتِكَ فِي دَارِ كَرَامَتِكَ وَمَحَلِّ مَغْفِرَتِكَ وَرَحْمَتِكَ، إنَّكَ ذُوالْفَضْلِ الْعَظِيمِ وَالْمَنِّ الْقَدِيْمِ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ."""

text_25 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ وَمُنَّ عَلَيَّ بِبَقَاءِ وُلْدِي، وَبِإصْلاَحِهِمْ لِي، وَبِإمْتَاعِي بِهِمْ.
إلهِي أمْدُدْ لِي فِي أَعْمَارِهِمْ، وَزِدْ لِي فِي آجَالِهِمْ، وَرَبِّ لِي صَغِيرَهُمْ وَقَوِّ لِي ضَعِيْفَهُمْ، وَأَصِحَّ لِي أَبْدَانَهُمْ وَأَدْيَانَهُمْ وَأَخْلاَقَهُمْ، وَعَافِهِمْ فِي أَنْفُسِهِمْ وَفِي جَوَارِحِهِمْ وَفِي كُلِّ مَا عُنِيْتُ بِهِ مِنْ أَمْرِهِمْ، وَأَدْرِرْ لِي وَعَلَى يَـدِي أَرْزَاقَهُمْ، وَاجْعَلْهُمْ أَبْرَاراً أَتْقِيَاءَ بُصَراءَ سَامِعِينَ مُطِيعِينَ لَكَ وَلاوْلِيَائِكَ مُحِبِّينَ مُنَاصِحِينَ، وَلِجَمِيْعِ أَعْدَآئِكَ مُعَانِدِينَ وَمُبْغِضِينَ آمِينَ.
أللَّهُمَّ اشْدُدْ بِهِمْ عَضُدِي، وَأَقِمْ بِهِمْ أَوَدِيْ، وَكَثِّرْ بِهِمْ عَدَدِي، وَزَيِّنْ بِهِمْ مَحْضَرِي، وَأَحْييِ بِهِمْ ذِكْرِي، وَاكْفِنِي بِهِمْ فِي غَيْبَتِي وَأَعِنِّي بِهِمْ عَلَى حَـاجَتِي، وَاجْعَلْهُمْ لِي مُحِبِّينَ، وَعَلَيَّ حَدِبِينَ مُقْبِلِينَ مُسْتَقِيمِينَ لِيْ، مُطِيعِينَ غَيْرَ عَاصِينَ وَلاَ عَاقِّينَ وَلا مُخَالِفِينَ وَلاَ خـاطِئِينَ،
وَأَعِنِّي عَلَى تَرْبِيَتِهِمْ وَتَأدِيْبِهِمْ وَبِرِّهِمْ، وَهَبْ لِيْ مِنْ لَدُنْكَ مَعَهُمْ أَوْلاداً ذُكُوراً، وَاجْعَلْ ذَلِكَ خَيْراً لي وَاجْعَلْهُمْ لِي عَوناً عَلَى مَا سَأَلْتُكَ، وَأَعِذْنِي وَذُرِّيَّتِي مِنَ الشَّيْطَانِ الرَّجِيمِ، فَإنَّكَ خَلَقْتَنَا وَأَمَرْتَنَا وَنَهَيْتَنَا وَرَغّبْتَنَا فِي ثَوَابِ ما أَمَرْتَنَا وَرَهَّبْتَنَا عِقَابَهُ، وَجَعَلْتَ لَنَا عَدُوّاً يَكِيدُنَا، سَلَّطْتَهُ مِنَّا عَلَى مَا لَمْ تُسَلِّطْنَا عَلَيْهِ مِنْهُ، أَسْكَنْتَهُ صُدُورَنَا، وَأَجْرَيْتَهُ مَجَارِيَ دِمَائِنَا، لاَ يَغْفُلُ إنْ غَفَلْنَا، وَلاَ يَنْسَى إنْ نَسِينَا، يُؤْمِنُنَا عِقَابَكَ، وَيَخَوِّفُنَا بِغَيْرِكَ، إنْ هَمَمْنَا بِفَاحِشَة شَجَّعَنَا عَلَيْهَا، وَإنْ هَمَمْنَا بِعَمَل صَالِح ثَبَّطَنَا عَنْهُ، يَتَعَرَّضُ لَنَا بِالشَّهَوَاتِ، وَيَنْصِبُ لَنَا بِالشَّبُهَاتِ، إنْ وَعَدَنَا كَذَبَنَا وَإنْ مَنَّانا، أَخْلَفَنَا وَالاّ تَصْرِفْ عَنَّا كَيْدَهُ يُضِلَّنَا، وَإلاّ تَقِنَا خَبالَهُ يَسْتَزِلَّنَا.
أللَّهُمَّ فَاقْهَرْ سُلْطَانَهُ عَنَّا بِسُلْطَانِكَ حَتَّى تَحْبِسَهُ عَنَّا بِكَثْرَةِ الدُّعَاءِ لَكَ، فَنُصْبحَ مِنْ كَيْدِهِ فِي الْمَعْصُومِينَ بِكَ.
أللَّهُمَّ أَعْطِنِي كُلَّ سُؤْلِي، وَاقْضِ لِي حَوَائِجِي، وَلاَ تَمْنَعْنِي الاجَابَةَ وَقَدْ ضَمِنْتَهَا لِي، وَلا تَحْجُبْ دُعَائِي عَنْكَ وَقَدْ أَمَرْتَنِي بِهِ، وَامْنُنْ عَلَيَّ بِكُلِّ مَا يُصْلِحُنِيْ فِيْ دُنْيَايَ وَآخِرَتِي مَا ذَكَرْتُ مِنْهُ وَمَـا نَسِيتُ، أَوْ أَظْهَـرتُ أَوْ أَخْفَيْتُ، أَوْ أَعْلَنْتُ أَوْ أَسْرَرْتُ، وَاجْعَلْنِي فِي جَمِيعِ ذلِكَ مِنَ الْمُصْلِحِينَ بِسُؤَالِي إيَّـاكَ، الْمُنْجِحِينَ بِالـطَّلَبِ إلَيْـكَ، غَيْـرِ الْمَمْنُوعِينَ بِالتَّوَكُّلِ عَلَيْكَ، الْمُعَوَّدِينَ بِالتَّعَوُّذِ بِكَ، الرَّابِحِينَ فِي التِّجَارَةِ عَلَيْـكَ، الْمُجَارِيْنَ بِعِـزِّكَ، الْمُـوَسَّـعِ عَلَيْهِمُ الـرِّزْقُ الْحَـلاَلُ مِنْ فَضْلِكَ الْوَاسِعِ بِجُودِكَ وَكَرَمِكَ، الْمُعَزِّينَ مِنَ الذُّلِّ بِكَ، وَالْمُجَارِينَ مِن الظُّلْمِ بِعَدْلِكَ، وَالْمُعَافَيْنَ مِنَ الْبَلاءِ بِرَحْمَتِكَ، وَالْمُغْنَيْنَ مِنَ الْفَقْرِ بِغِنَاكَ، وَالْمَعْصومِينَ مِنَ الذُّنُوبِ وَالزَّلَلِ وَالْخَطَأِ بِتَقْوَاكَ، وَالْمُوَفَّقِينَ لِلْخَيْرِ وَالرُّشْدِ وَالصَّوَابِ بِطَاعَتِكَ، وَالْمُحَالِ بَيْنَهُمْ وَبَيْنَ الذُّنُوبِ بِقُدْرَتِكَ، التَّـارِكِينَ لِكُلِّ مَعْصِيَتِكَ، السَّاكِنِينَ فِي جِوَارِكَ.
أللَّهُمَّ أَعْطِنَا جَمِيعَ ذلِكَ بِتَوْفِيقِكَ وَرَحْمَتِكَ، وَأَعِذْنَا مِنْ عَذَابِ السَّعِيرِ، وَأَعْطِ جَمِيـعَ الْمُسْلِمِينَ وَالْمُسْلِمَـاتِ وَالْمُؤْمِنِيْنَ وَالْمُؤْمِنَاتِ مِثْلَ الَّذِي سَأَلْتُكَ لِنَفْسِي وَلِوُلْدِي فِي عَاجِلِ الدُّنْيَا وَآجِلِ الاخِرَةِ، إنَّكَ قَرِيبٌ مُجِيبٌ سَمِيعٌ عَلِيمٌ عَفُوٌّ غَفُـورٌ رَؤُوفٌ رَحِيمٌ.
وَآتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ."""

text_26 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ صَـلِّ عَلَى مُحَمَّد وَآلِـهِ وَتَـوَلَّنِي فِي جيرَانِي وَمَوَالِيَّ وَالْعَـارِفِينَ بحَقِّنَا وَالْمُنَـابِذِينَ لاِعْدَائِنَا بِأَفْضَلِ وَلاَيَتِكَ،
وَوَفِّقْهُمْ لاقَامَةِ سُنَّتِكَ وَالاَخْذِ بِمَحَاسِنِ أَدَبِكَ فِي إرْفَاقِ ضَعِيفِهِمْ، وَسَدِّ خَلَّتِهِمْ، وَعِيَادَةِ مَرِيضِهِمْ، وَهِـدَايَةِ مُسْتَـرْشِدِهِمْ، وَمُنَاصَحَةِ مُسْتَشِيرِهِمْ، وَتَعَهُّدِ قَـادِمِهِمْ، وَكِتْمَانِ أَسْرَارِهِمْ، وَسَتْرِ عَوْرَاتِهِمْ، وَنُصْرَةِ مَظْلُومِهِمْ، وَحُسْنِ مُوَاسَاتِهِمْ بِالْمَاعُونِ، وَالْعَوْدِ عَلَيْهِمْ بِـالْجِـدَةِ وَالاِفْضَـالِ، وَإعْطَآءِ مَـا يَجِبُ لَهُمْ قَبْلَ السُّؤالِ واجْعَلْنِي اللَّهُمَّ أَجْزِي بِالاحْسَانِ مُسِيْئَهُمْ، وَاعْرِضُ بِالتَّجَاوُزِ عَنْ ظَالِمِهِمْ،
وَأَسْتَعْمِلْ حُسْنَ الظّنِّ فِي كَافَّتِهِمْ، وَأَتَوَلَّى بِالْبِرِّ عَامَّتَهُمْ، وَأَغُضُّ بَصَرِي عَنْهُمْ عِفَّةً، وَألِينُ جَانِبِيْ لَهُمْ تَوَاضُعاً، وَأَرِقُّ عَلَى أَهْلِ الْبَلاءِ مِنْهُمْ رَحْمَةً، وَأسِرُّ لَهُمْ بِالْغَيْبِ مَوَدَّةً، وَاُحِبُّ بَقَاءَ النِّعْمَةِ عِنْدَهُمْ نُصْحاً، وَاُوجِبُ لَهُمْ مَا اُوجِبُ لِحَامَّتِي، وَأَرْعَى لَهُمْ مَا أَرْعَى لِخَاصَّتِي.
أَللَّهُمَّ صَلِّ عَلَى مُحَمِّد وَآلِهِ، وَارْزُقْنِي مِثْلَ ذَلِكَ مِنْهُمْ، وَاجْعَلْ لِي أَوْفَى الْحُظُوظِ فِيمَا عِنْدَهُمْ، وَزِدْهُمْ بَصِيْرَةً فِي حَقِّي، وَمَعْرِفَةً بِفَضْلِي، حَتَّى يَسْعَدُوا بِي وَأَسْعَدَ بِهِمْ آمِينَ رَبَّ الْعَالَمِينَ."""

text_27 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أَللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَحَصِّنْ ثُغُورَ الْمُسْلِمِينَ بِعِزَّتِكَ، وَأَيِّدْ حُمَاتَهَا بِقُوَّتِكَ، وَأَسْبغَ عَطَايَاهُمْ مِنْ جِدَتِكَ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَكَثِّرْ عِدَّتَهُمْ، وَاشْحَذْ أَسْلِحَتَهُمْ، وَاحْرُسْ حَوْزَتَهُمْ، وَامْنَعْ حَوْمَتَهُمْ، وَأَلِّفْ جَمْعَهُمْ، وَدَبِّرْ أَمْرَهُمْ، وَوَاتِرْ بَيْنَ مِيَرِهِمْ، وَتَوَحَّدْ بِكِفَايَةِ مَؤَنِهِمْ، وَاعْضُدْهُمْ بِالنَّصْرِ، وَأَعْنِهُمْ بِالصَّبْرِ، وَالْطُفْ لَهُمْ فِي الْمَكْرِ.
أَللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَعَرِّفْهُمْ مَا يَجْهَلُونَ، وَعَلِّمْهُمْ مَا لاَ يَعْلَمُونَ، وَبَصِّرْهُمْ مَا لاَ يُبْصِرُونَ. أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَأَنْسِهِمْ عِنْدَ لِقَآئِهِمُ الْعَدُوَّ ذِكْرَ دُنْيَاهُمُ الْخَدَّاعَةِ الْغَرُورِ، وَامْحُ عَنْ قُلُوبِهِمْ خَطَرَاتِ الْمَالِ الْفَتُونِ، وَاجْعَلِ الْجَنَّـةَ نَصْبَ أَعْيُنِهِمْ وَلَوِّحْ مِنْهَا لاِبْصَارِهِمْ مَا أَعْدَدْتَ فِيهَا مِنْ مَسَاكِنِ الْخُلْدِ وَمَنَازِلِ الْكَرَامَةِ وَالْحُورِ الْحِسَانِ وَالاَنْهَارِ الْمُـطَّرِدَةِ بِأَنْوَاعِ الاَشْرِبَـةِ، وَالاَشْجَارِ الْمُتَدَلِّيَةِ بِصُنُوفِ الثَّمَرِ، حَتَّى لاَ يَهُمَّ أَحَدٌ مِنْهُمْ بِالادْبَارِ، وَلا يُحَدِّثَ نَفْسَهُ عَنْ قِرْنِهِ بِفِرَار.
أللَّهُمَّ افْلُلْ بِذَلِـكَ عَدُوَّهُمْ، وَاقْلِمْ عَنْهُمْ أَظْفَارَهُمْ، وَفَرِّقْ بَيْنَهُمْ وَبَيْنَ أَسْلِحَتِهِمْ، وَاخْلَعْ وَثَائِقَ أَفْئِدَتِهِمْ، وَبَاعِدْ بَيْنَهُمْ وَبَيْنَ أَزْوِدَتِهِمْ، وَحَيِّرْهُمْ فِي سُبُلِهِمْ، وَضَلِّلْهُمْ عَنْ وَجْهِهِمْ، وَاقْـطَعْ عَنْهُمُ الْمَدَدَ وَانْقُصْ مِنْهُمُ الْعَدَدَ، وَامْلاْ أَفْئِدَتَهُمُ الرُّعْبَ، وَاقْبِضْ أَيْـدِيَهُمْ عَنِ البَسْطِ، وَاخْـزِمْ أَلْسِنَتَهُمْ عَنِ النُّطْقِ، وَشَـرِّدْ بهِمْ مَنْ خَلْفَهُمْ، وَنَكِّـلْ بِهِمْ مَنْ وَرَاءَهُمْ، وَاقْـطَعْ بِخِزْيِهِمْ أَطْمَـاعَ مَنْ بَعْدَهُمْ.
أللَّهُمَّ عَقِّمْ أَرْحَامَ نِسَائِهِمْ، وَيَبِّسْ أَصْلاَبَ رِجَالِهِمْ، وَاقْطَعْ نَسْلَ دَوَابِّهِمْ وَأَنْعَامِهِمْ، لاَ تَأذَنْ لِسَمَائِهِمْ فِي قَطْر وَلاَ لارْضِهِمْ فِي نَبَات. أللَّهُمَّ وَقَوِّ بِذَلِكَ مِحَالَّ أَهْلِ الاسْلاَمِ، وَحَصِّنْ بِهِ دِيَارَهُمْ، وَثَمِّرْ بِـهِ أَمْوَالَهُمْ، وَفَرِّغْهُمْ عَنْ مُحَارَبَتِهِمْ لِعِبَادَتِكَ وَعَنْ مُنَابَذَتِهِمْ للْخَلْوَةِ بِكَ، حَتَّى لا يُعْبَدَ فِي بِقَاعِ الارْضِ غَيْرُكَ وَلاَ تُعَفَّرَ لِاَحَد مِنْهُمْ جَبْهَةٌ دُونَكَ.
أللَّهُمَّ اغزُ بِكُلِّ نَـاحِيَـة مِنَ الْمُسْلِمِينَ عَلَى مَنْ بِـإزَائِهِمْ مِنَ الْمُشْرِكِينَ، وَأَمْدِدْهُمْ بِمَلائِكَة مِنْ عِنْدِكَ مُرْدِفِينَ حَتَّى يَكْشِفُـوهُمْ إلَى مُنْقَطَعِ التُّـرابِ قَتْـلاً فِي أَرْضِكَ وَأَسْراً أَوْ يُقِرُّوا بِأَنَّكَ أَنْتَ اللهُ الَّذِي لاَ إلهَ إلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ.
أللَّهُمَّ وَاعْمُمْ بِذَلِكَ أَعْدَاءَكَ فِي أَقْطَارِ الْبِلاَدِ مِنَ الْهِنْدِ وَالرُّومِ وَالتُّـرْكِ وَالْخَزَرِ وَالْحَبَشِ وَالنُّـوبَةِ وَالـزِّنْـج والسَّقَالِبَةِ وَالدَّيَالِمَةِ وَسَائِرِ اُمَمِ الشِّرْكِ الَّذِي تَخْفَى أَسْمَاؤُهُمْ وَصِفاتُهُمْ، وَقَدْ أَحْصَيْتَهُمْ بِمَعْرِفَتِكَ، وَأَشْرَفْتَ عَلَيْهِمْ بِقُدْرَتِكَ. أللَّهُمَّ اشْغَلِ الْمُشْرِكِينَ بِالمُشْرِكِينَ عَنْ تَنَاوُلِ أَطْرَافِ الْمُسْلِمِينَ، وَخُذْهُمْ بِـالنَّقْصِ عَنْ تَنَقُّصِهِمْ، وَثَبِّطْهُمْ بِـالْفُـرْقَـةِ عَنِ الاحْتِشَادِ عَلَيْهِمْ.
أللَّهُمَّ أَخْلِ قُلُوبَهُمْ مِنَ الاَمَنَـةِ وَأَبْدَانَهُمْ مِنَ الْقُوَّةِ وَأَذْهِلْ قُلُوبَهُمْ عَنِ الاحْتِيَالِ وَأَوْهِنْ أَرْكَانَهُمْ عَنْ مُنَازَلَةِ الرِّجَالِ وَجَبِّنْهُمْ عَنْ مُقَارَعَةِ الاَبْطَالِ، وَابْعَثْ عَلَيْهِمْ جُنْداً مِنْ مَلاَئِكَتِكَ بِبَأس مِنْ بَأْسِكَ كَفِعْلِكَ يَوْمَ بَدْر تَقْطَعُ بِهِ دَابِرَهُمْ وَتَحْصُدُ بِهِ شَوْكَتَهُمْ، وَتُفَرِّقُ بهِ عَدَدَهُمْ.
اللَّهُمَّ وَامْزُجْ مِيَاهَهُمْ بِالْوَبَاءِ وَأطْعِمَتَهُمْ بِالاَدْوَاءِ وَارْمِ بِلاَدَهُمْ بِـالْخُسُوفِ وَأَلِـحَّ عَلَيْهَا بِـالْقُذُوفِ وَافْـرَعْهَا بِالْمُحُولِ. وَاجْعَلْ مِيَرَهُمْ فِي أَحَصِّ أَرْضِكَ وَأَبْعَـدِهَا عَنْهُمْ، وَامْنَـعْ حُصُونَهَا مِنْهُمْ، أَصِبْهُمْ بِالْجُوعِ الْمُقِيمِ وَالسُّقْمِ الالِيمِ.
أللَّهُمَّ وَأَيُّمَا غَاز غَزَاهُمْ مِنْ أَهْلِ مِلَّتِكَ أَوْ مُجَاهِد جَاهَدَهُمْ مِنْ أَتْبَاعِ سُنَّتِكَ لِيَكُونَ دِينُكَ الاعْلَى وَحِزْبُكَ الاقوَى وَحَظُّكَ الاوْفَى فَلَقِّهِ الْيُسْرَ، وَهَيِّئْ لَهُ الامْرَ، وَتَوَلَّهُ بِالنُّجْحِ، وَتَخَيَّرْ لَهُ الاصْحَابَ، وَاسْتَقْوِ لَهُ الظَّهْرَ، وَأَسْبِغْ عَلَيْهِ فِي النَّفَقَةِ وَمَتِّعْهُ بِالنَّشَاطِ، وَأَطْفِ عَنْهُ حَرَارَةَ الشَّوْقِ، وَأَجِرْهُ مِنْ غَمِّ الْوَحْشَةِ، وَأَنْسِهِ ذِكْرَ الاهْلِ وَالْوَلَدِ وَأَثُرْ لَهُ حُسْنَ النِّيَّةِ وَتَوَلَّه بِالْعَافِيَةِ، وَأَصْحِبْهُ السَّلاَمَةَ، وَأَعْفِهِ مِنَ الْجُبْنِ، وَأَلْهِمْهُ الْجُرْأَةَ وَارْزُقْهُ الشِّدَّةَ وَأَيِّدْهُ بِالنُّصْرَةِ، وَعَلِّمْهُ السِّيَرَ وَالسُّنَنَ، وَسَدِّدْهُ فِي الْحُكْمِ، وَاعْزِلْ عَنْهُ الرِّياءَ، وخَلِّصْهُ مِنَ السُّمْعَةِ وَاجْعَلْ فِكْرَهُ وَذِكْرَهُ وَظَعْنَهُ وَإقَامَتَهُ فِيْكَ وَلَكَ، فَإذا صَافَّ عَدُوَّكَ وَعَدُوَّهُ فَقَلِّلْهُمْ فِي عَيْنِهِ وَصَغِّرْ شَأنَهُمْ فِي قَلْبِهِ وَأَدِلْ لَهُ مِنْهُـمْ وَلاَ تُدِلْهُمْ مِنْهُ فَإنْ خَتَمْتَ لَهُ بِالسَّعَادَةِ وَقَضَيْتَ لَهُ بِالشَّهَادَةِ فَبَعْدَ أَنْ يَجْتَاحَ عَدُوَّكَ بِالْقَتْلِ وَبَعْدَ أنْ يَجْهَدَ بِهِمُ الاسْرُ وَبَعْدَ أن تَأمَنَ أطرَافُ المُسْلِمِينَ وَبَعْدَ أَنْ يُوَلِّيَ عَدُوُّكَ مُدْبِرِينَ.
أللَّهُمَّ وَأَيُّمَا مُسْلِم خَلَفَ غَازِياً أَوْ مُرَابِطاً فِي دَارِهِ أَوْ تَعَهَّدَ خَالِفِيْهِ فِيْ غَيْبَتِهِ، أَوْ أَعَانَهُ بِطَائِفَة مِنْ مَالِهِ، أَوْ أَمَدَّهُ بِعِتَاد، أَوْ شَحَذَهُ عَلَى جِهَاد، أَوْ أَتْبَعَهُ فِي وَجْهِهِ دَعْوَةً، أَوْ رَعَى لَهُ مِنْ وَرَآئِهِ حُرْمَةً.
فَأَجْرِ لَهُ مِثْلَ أَجْرِهِ وَزْناً بِوَزْن وَمِثْلاً بِمِثْل وَعَوِّضْهُ مِنْ فِعْلِهِ عِوَضاً حَاضِراً يَتَعَجَّلُ بِهِ نَفْعَ مَا قَدَّمَ، وَسُرُورَ مَا أَتَى به، إلَى أَنْ يَنْتَهِيَ بِهِ الْوَقْتُ إلَى مَا أَجْرَيْتَ لَـهُ مِنْ فَضْلِكَ، وَأَعْدَدْتَ لَهُ مِنْ كَرَامَتِكَ.
أللَّهُمَّ وَأَيُّمَا مُسْلِم أَهَمَّهُ أَمْرُ الاِسْلاَمِ وَأَحْزَنَهُ تَحَزُّبُ أَهْلِ ألشِّرْكِ عَلَيْهِمْ فَنَوَى غَزْواً أَوْ هَمَّ بِجهَـاد فَقَعَدَ بِـهِ ضَعْفٌ أَوْ أَبطَأَتْ بِهِ فَاقَةٌ، أَوْ أَخَّرَهُ عَنْهُ حَادِثٌ، أَوْ عَرَضَ لَهُ دُونَ إرَادَتِهِ مَانِعٌ، فَاكْتُبِ اسْمَـهُ فِي الْعَابِـدِينَ وَأوْجبْ لَهُ ثَوَابَ الْمُجَاهِدِينَ وَاجْعَلْهُ فِي نِظَامِ الشُّهَـدَآءِ وَالصَّالِحِينَ. أللَّهُمَّ صَـلِّ عَلَى مُحَمَّد عَبْدِكَ وَرَسُولِكَ وَآلِ مُحَمَّد صَلاَةً عَالِيَةً عَلَى الصَّلَوَاتِ مُشْرِفَةً فَوْقَ التَّحِيَّاتِ، صَلاَةً لاَ يَنْتَهِي أَمَدُهَا وَلا يَنْقَطِعُ عَدَدُهَـا كَأَتَمِّ مَـا مَضَى مِنْ صَلَوَاتِكَ عَلَى أَحَد مِنْ أَوْلِيـآئِكَ، إنَّـكَ الْمَنَّانُ الْحَمِيدُ الْمُبْدِئُ الْمُعِيدُ الفَعَّالُ لِمَا تُرِيْدُ."""

text_28 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
اللَهُمَّ إنِّي أَخْلَصْتُ بِانْقِطَاعِي إلَيْكَ، وَأَقْبَلْتُ بِكُلِّي عَلَيْـكَ، وَصَـرَفْتُ وَجْهِي عَمَّنْ يَحْتَـاجُ إلَى رِفْدِكَ، وَقَلَبْتُ مَسْأَلَتِي عَمَّنْ لَمْ يَسْتَغْنِ عَنْ فَضْلِكَ، وَرَأَيْتُ أَنَّ طَلَبَ الْمُحْتَاجِ إلَى الْمُحْتَاجِ سَفَهٌ مِنْ رَأيِهِ وَضَلَّةٌ مِنْ عَقْلِهِ، فَكَمْ قَدْ رَأَيْتُ يَـا إلهِيْ مِنْ اُناس طَلَبُوا الْعِزَّ بِغَيْرِكَ فَذَلُّوا، وَرَامُوا الثَّرْوَةَ مِنْ سِوَاكَ فَافْتَقَرُوا، وَحَاوَلُوا الارْتِفَاعَ فَاتَّضَعُوا، فَصحَّ بِمُعَايَنَةِ أَمْثَالِهِمْ حَازِمٌ وَفَّقَهُ اعْتِبَارُهُ وَأَرْشَدَهُ إلَى طَرِيقِ صَوَابِهِ بِاخْتِبَارِهِ فَأَنْتَ يَا مَوْلايَ دُونَ كُلِّ مَسْؤُول مَوْضِعُ مَسْأَلَتِي وَدُونَ كُلِّ مَطْلُوب إلَيْهِ وَلِيُّ حَاجَتِي.
أَنْتَ الْمَخْصُوصُ قَبْلَ كُلِّ مَدْعُوٍّ بِدَعْوَتِي لاَ يَشْرَكُكَ أَحَدٌ فِي رَجَائِي، وَلاَ يَتَّفِقُ أَحَدٌ مَعَكَ فِي دُعَائِي، وَلاَ يَنْظِمُهُ وَإيَّاكَ نِدَائِي لَكَ يَا إلهِي وَحْدَانِيَّةُ الْعَدَدِ، وَمَلَكَةُ الْقُدْرَةِ الصَّمَدِ، وَفَضِيلَةُ الْحَوْلِ وَالْقُوَّةِ، وَدَرَجَةُ الْعُلُوِّ وَالرِّفْعَةِ وَمَنْ سِوَاكَ مَرْحُومٌ فِي عُمْرِهِ، مَغْلُوبٌ عَلَى أَمْرِهِ، مَقْهُورٌ عَلَى شَأنِهِ، مُخْتَلِفُ الْحَالاَتِ، مُتَنَقِّلٌ فِي الصِّفَاتِ.
فَتَعَالَيْتَ عَنِ الاشْبَاهِ وَالاضْـدَادِ، وَتَكَبَّـرْتَ عَنِ الامْثَـالِ وَالانْدَادِ، فَسُبْحَانَكَ لاَ إلهَ إلاَّ أَنْتَ."""

text_29 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أَللَّهُمَّ إنَّكَ ابْتَلَيْتَنَا فِي أَرْزَاقِنَا بِسُوءِ الظَّنِّ وَفِي آجَالِنَا بِطُولِ الامَلِ حَتَّى الْتَمَسْنَا أَرْزَاقَكَ مِنْ عِنْدِ الْمَرْزُوقِينَ، وَطَمِعْنَا بِآمَالِنَا فِي أَعْمَارِ الْمُعَمَّرِينَ.
فَصَلِّ عَلَى مُحَمَّد وَآلِهِ، وَهَبْ لَنَا يَقِيناً صَادِقاً تَكْفِينا بِهِ مِنْ مَؤونَةِ الطَّلَبِ، وَأَلْهِمْنَا ثِقَةً خَالِصَةً تُعْفِينَا بِهَا مِنْ شِدَّةِ النَّصَبِ، وَاجْعَلْ مَا صَرَّحتَ بِهِ مِنْ عِدَتِكَ فِي وَحْيِكَ، وَأَتْبَعْتَهُ مِنْ قِسَمِكَ فِي كِتَابِكَ قَاطِعاً لاهْتِمَامِنَا بِـالرِّزْقِ الَّـذِيْ تَكَفَّلْتَ بِهِ وَحَسْمَاً لِلاشْتِغَالِ بِمَا ضَمِنْتَ الْكِفَايَةَ لَهُ، فَقُلْتَ وَقَوْلُكَ الْحَقُّ الاصْـدَقُ وَأَقْسَمْتَ وَقَسَمُكَ الاَبَرُّ الاَوْفى: ﴿وَفِي آلسَّمَاءِ رِزْقُكُمْ وَمَا تُوعَدُونَ﴾ ثُمَّ قُلْتَ: (﴿فَوَ رَبِّ السَّمَاءِ وَالاَرْضِ إنَّهُ لَحَقٌّ مِثْلَ مَا أَنَّكُمْ تَنْطِقُوْنَ﴾."""

